import{_ as r,o as a,c as o,a2 as t}from"./chunks/framework.DYAmjhAm.js";const f=JSON.parse('{"title":"Class: ValidationError","description":"","frontmatter":{},"headers":[],"relativePath":"api/classes/ValidationError.md","filePath":"api/classes/ValidationError.md","lastUpdated":null}'),i={name:"api/classes/ValidationError.md"};function d(n,e,s,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<p><a href="./../">breeze-client</a> / ValidationError</p><h1 id="class-validationerror" tabindex="-1">Class: ValidationError <a class="header-anchor" href="#class-validationerror" aria-label="Permalink to &quot;Class: ValidationError&quot;">​</a></h1><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/validation/validate.ts#L975" target="_blank" rel="noreferrer">src/validation/validate.ts:975</a></p><p>Describes one failed validation: which validator failed, on which property, and the message to show. An entity&#39;s current errors are in <a href="./EntityAspect#getvalidationerrors">EntityAspect.getValidationErrors</a>. The errors a server reports for a failed save are added there too, with <a href="#isservererror">ValidationError.isServerError</a> set.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h3><blockquote><p><strong>new ValidationError</strong>(<code>validator</code>, <code>context</code>, <code>errorMessage</code>, <code>key?</code>): <code>ValidationError</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/validation/validate.ts#L1002" target="_blank" rel="noreferrer">src/validation/validate.ts:1002</a></p><p>Creates a validation error. Applications usually add one with <a href="./EntityAspect#addvalidationerror">EntityAspect.addValidationError</a> after creating it here.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="validator" tabindex="-1">validator <a class="header-anchor" href="#validator" aria-label="Permalink to &quot;validator&quot;">​</a></h5><p><a href="./Validator"><code>Validator</code></a> | <code>null</code></p><p>The Validator that found the error, or <code>null</code> for an error found some other way.</p><h5 id="context" tabindex="-1">context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;context&quot;">​</a></h5><p><a href="./../interfaces/ValidationContext"><code>ValidationContext</code></a></p><p>The context to record with the error: for a property, its <code>entity</code>, <code>property</code>, <code>propertyName</code> and <code>value</code>.</p><h5 id="errormessage" tabindex="-1">errorMessage <a class="header-anchor" href="#errormessage" aria-label="Permalink to &quot;errorMessage&quot;">​</a></h5><p><code>string</code></p><p>The message to show.</p><h5 id="key" tabindex="-1">key? <a class="header-anchor" href="#key" aria-label="Permalink to &quot;key?&quot;">​</a></h5><p><code>string</code></p><p>Identifies the error among the entity&#39;s errors. If not given, it is built from the validator&#39;s name - or, without a validator, the error message - and the property name; see <a href="#getkey">ValidationError.getKey</a>.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>ValidationError</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="context-1" tabindex="-1">context <a class="header-anchor" href="#context-1" aria-label="Permalink to &quot;context&quot;">​</a></h3><blockquote><p><strong>context</strong>: <code>any</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/validation/validate.ts#L981" target="_blank" rel="noreferrer">src/validation/validate.ts:981</a></p><p>The context the error was created with - for a validator, its context when it ran, which for a property error includes <code>entity</code>, <code>property</code>, <code>propertyName</code> and <code>value</code>. <strong>Read Only</strong></p><hr><h3 id="errormessage-1" tabindex="-1">errorMessage <a class="header-anchor" href="#errormessage-1" aria-label="Permalink to &quot;errorMessage&quot;">​</a></h3><blockquote><p><strong>errorMessage</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/validation/validate.ts#L983" target="_blank" rel="noreferrer">src/validation/validate.ts:983</a></p><p>The error message. <strong>Read Only</strong></p><hr><h3 id="isservererror" tabindex="-1">isServerError <a class="header-anchor" href="#isservererror" aria-label="Permalink to &quot;isServerError&quot;">​</a></h3><blockquote><p><strong>isServerError</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/validation/validate.ts#L989" target="_blank" rel="noreferrer">src/validation/validate.ts:989</a></p><p>Whether this error came from the server in a failed save. Server errors do not block a save, and are cleared when the property is changed or the entity is saved again. <strong>Read Only</strong></p><hr><h3 id="key-1" tabindex="-1">key <a class="header-anchor" href="#key-1" aria-label="Permalink to &quot;key&quot;">​</a></h3><blockquote><p><strong>key</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/validation/validate.ts#L979" target="_blank" rel="noreferrer">src/validation/validate.ts:979</a></p><p>The key that identifies this error among an entity&#39;s validation errors: the validator&#39;s name (or the error name), then <code>:</code> and the property name if there is one. Adding an error with the same key replaces the old one. <strong>Read Only</strong></p><hr><h3 id="property" tabindex="-1">property <a class="header-anchor" href="#property" aria-label="Permalink to &quot;property&quot;">​</a></h3><blockquote><p><strong>property</strong>: <code>any</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/validation/validate.ts#L985" target="_blank" rel="noreferrer">src/validation/validate.ts:985</a></p><p>The <a href="./DataProperty">DataProperty</a> or <a href="./NavigationProperty">NavigationProperty</a> this error is about, or <code>undefined</code> for an entity-level error. <strong>Read Only</strong></p><hr><h3 id="propertyname" tabindex="-1">propertyName? <a class="header-anchor" href="#propertyname" aria-label="Permalink to &quot;propertyName?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>propertyName?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/validation/validate.ts#L987" target="_blank" rel="noreferrer">src/validation/validate.ts:987</a></p><p>The name of the property this error is about - a property path, such as <code>address.city</code>, for a property of a complex object - or <code>undefined</code> for an entity-level error. <strong>Read Only</strong></p><hr><h3 id="validator-1" tabindex="-1">validator? <a class="header-anchor" href="#validator-1" aria-label="Permalink to &quot;validator?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>validator?</strong>: <a href="./Validator"><code>Validator</code></a></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/validation/validate.ts#L977" target="_blank" rel="noreferrer">src/validation/validate.ts:977</a></p><p>The <a href="./Validator">Validator</a> that produced this error. <code>undefined</code> for an error from the server or one created without a validator. <strong>Read Only</strong></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="getkey" tabindex="-1">getKey() <a class="header-anchor" href="#getkey" aria-label="Permalink to &quot;getKey()&quot;">​</a></h3><blockquote><p><code>static</code> <strong>getKey</strong>(<code>validatorOrErrorName</code>, <code>propertyName?</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/validation/validate.ts#L1029" target="_blank" rel="noreferrer">src/validation/validate.ts:1029</a></p><p>Composes a ValidationError &#39;key&#39; given a validator or an errorName and an optional propertyName</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="validatororerrorname" tabindex="-1">validatorOrErrorName <a class="header-anchor" href="#validatororerrorname" aria-label="Permalink to &quot;validatorOrErrorName&quot;">​</a></h5><p><code>string</code> | <a href="./Validator"><code>Validator</code></a></p><p>A Validator, or an &quot;error name&quot; if no validator is available.</p><h5 id="propertyname-1" tabindex="-1">propertyName? <a class="header-anchor" href="#propertyname-1" aria-label="Permalink to &quot;propertyName?&quot;">​</a></h5><p><code>string</code></p><p>A property name</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>string</code></p><p>A ValidationError &#39;key&#39;</p>',74)])])}const b=r(i,[["render",d]]);export{f as __pageData,b as default};
